'use strict';
txt('站点与工作区','Sites & workspace');txt('开始使用','Getting started');txt('发布与任务','Publishing & tasks');
const setupStatusWords={queued:['待运维处理','Awaiting operations'],working:['开通中','In progress'],info:['待补充资料','Information needed'],partial:['部分开通','Partially ready'],blocked:['待运维处理','Operations follow-up'],verifying:['核验中','Verifying'],complete:['已开通','Ready']};
function setupStatus(r){return badge(txt(...setupStatusWords[r.status]),r.status==='complete'?'green':r.status==='info'||r.status==='blocked'?'amber':'purple',true);}
function setupField(id,zh,en,value='',area=false,max=1000){return `<div class="modal-field"><label for="${id}">${txt(zh,en)}</label>${area?`<textarea id="${id}" maxlength="${max}" rows="3">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}" maxlength="${max}">`}</div>`;}
function setupHint(){return `<p class="setup-caption">${txt('原型演示：不会创建真实资源或执行发布。','Prototype only: no real resources are created and no content is published.')}</p>`;}
function setupProgress(r){
  const current=r.status==='queued'?1:r.status==='info'||r.status==='working'?2:r.status==='complete'?4:3;
  const copy=r.status==='complete'?txt('两种语言及根路径跳转均已通过核验。','Both languages and the root redirect passed verification.'):r.status==='info'?txt('请补充下方资料，运维会继续处理同一申请。','Provide the information below so operations can continue this request.'):txt('运维正在跟进。可以继续使用内容库和编辑器，进度会显示在这里。','Operations will follow up here. You can continue using the content library and editor.');
  return `<section class="panel setup-progress"><div class="section-heading"><h2>${txt('开通进度','Setup progress')}</h2>${setupStatus(r)}</div><p>${copy}</p><ol class="setup-steps">${[['已申请','Requested'],['运维开通','Provisioning'],['站点核验','Verification'],['已就绪','Ready']].map((pair,i)=>`<li class="${current>i+1?'done':current===i+1?'current':''}"><span>${current>i+1?'✓':i+1}</span>${txt(...pair)}</li>`).join('')}</ol><div class="setup-meta"><span data-i18n-preserve>${esc(r.name)} · ${esc(r.id)}</span><span>${r.assignee?txt('由运维团队处理','Assigned to operations'):txt('等待运维接单','Waiting for operations')}</span></div>${r.status==='info'?notice(esc(r.infoReason))+ (canApplySetup(r.owner)?flowButton('补充资料','Provide information','setup-supplement','','soft'):notice(txt('等待当前组织 Admin 补充资料。','Waiting for this organization’s Admin to respond.'))):''}</section>`;
}
function setupLanguageCard(lang){
  const ready=isSiteReady(state.workspace,lang),r=setupData.requests[state.workspace],s=r?.sites[lang];
  const status=ready?txt('已开通','Ready'):s?.status==='failed'?txt('核验未通过','Check failed'):r?txt('开通中','In progress'):txt('未开通','Not configured');
  const url=s?.url||(ready?publicationTarget(state.workspace,lang).url:'');
  return `<section class="panel setup-language"><div class="section-heading"><h3>${lang==='en'?'English':'简体中文'}</h3>${badge(status,ready?'green':'amber',true)}</div><p class="setup-address" data-i18n-preserve>${esc(url||txt('开通后显示访问地址','The address appears after setup'))}</p><p>${txt('独立 Ghost，单独管理文章和发布状态。','Independent Ghost instance, articles and publication state.')}</p>${ready?flowButton('访问博客','View blog','open-public-site',state.workspace+':'+lang,'quiet'): `<span class="setup-caption">${r?txt('运维会在当前申请中继续处理。','Operations will continue in the current request.'):txt('可以先在现有编辑器中保存草稿。','You can save drafts in the existing editor.')}</span>`}</section>`;
}
function setupActivity(r){
  const labels={submitted:['已提交开通申请','Setup requested'],claimed:['运维已接单','Claimed by operations'],info:['需要补充资料','More information requested'],supplement:['已补充资料','Information provided'],'root-registered':['已登记博客地址','Blog root registered'],'root-changed':['地址已更新，需重新核验','Address changed; recheck required'],verified:['语言站点核验通过','Language verified'],failed:['语言站点核验失败','Language check failed'],'root-verified':['根路径跳转英文已核验','English root redirect verified'],'root-failed':['根路径跳转待处理','Root redirect needs attention'],complete:['开通完成','Setup completed']};
  return `<details class="panel setup-history"><summary>${txt('处理记录','Activity')} <span class="mono">${esc(r.id)}</span></summary><ol class="timeline">${r.events.slice().reverse().map(e=>`<li>${txt(...(labels[e.type]||['配置记录更新','Configuration updated']))}${e.language?' · '+e.language.toUpperCase():''}<small>${esc(new Date(e.at).toLocaleString())}</small>${e.note?`<p data-i18n-preserve>${esc(e.note)}</p>`:''}</li>`).join('')}</ol></details>`;
}
function setupSettingsPage(){
  if(setupView.mode==='ops')return setupOperatorPage();
  const owner=state.workspace,r=setupData.requests[owner],c=site.settings[owner],both=['en','zh'].every(l=>isSiteReady(owner,l));
  const root=r?.rootUrl||(['en','zh'].some(l=>isSiteReady(owner,l))?publicationTarget(owner,'en').rootUrl:'');
  const returnLink=setupView.returnEditor?.owner===owner?flowButton('返回刚才的文章','Return to article','setup-return-editor','','quiet'):'';
  return titleBlock('','站点与工作区',txt('当前工作区的博客地址、开通进度和公开资料。','Blog addresses, setup progress and public profile for this workspace.'),returnLink)+
  (setupStorageError?notice(txt('浏览器存储不可用，本次开通进度仅保留在当前页面。','Browser storage is unavailable; setup progress lasts for this page only.')):'')+
  (!r&&!both?`<section class="panel setup-request"><div><h2>${txt('开通当前工作区的博客','Set up this workspace’s blog')}</h2><p>${txt('提交一次申请，由运维准备双语站点。已有站点会保留，文章继续在原编辑器中创作。','Send one request for operations to prepare both languages. Existing sites are retained; articles stay in the existing editor.')}</p></div>${canApplySetup()?flowButton('申请开通博客','Request blog setup','setup-apply','','primary'):badge(txt('由组织 Admin 申请','Organization Admin required'),'amber')}</section>`:r?setupProgress(r):'')+
  `<section class="panel setup-root-summary"><div><h2>${txt('博客地址','Blog address')}</h2><p class="setup-address" data-i18n-preserve>${esc(root||txt('由运维分配平台子域名','Operations assigns a platform subdomain'))}</p><p>${txt('英文 /en/ · 中文 /zh/ · 根路径默认跳转英文。','English /en/ · Chinese /zh/ · the root opens English.')}</p></div>${root&&isSiteReady(owner,'en')&&(!r||r.rootCheck.status==='passed')?flowButton('访问博客首页','Open blog home','setup-root-preview','','soft'):badge(txt('等待开通核验','Awaiting verification'),'neutral')}</section><div class="setup-language-grid">${setupLanguageCard('en')}${setupLanguageCard('zh')}</div>`+
  (r?setupActivity(r):'')+
  `<details class="panel setup-profile"><summary>${txt('工作区资料与权限','Workspace profile & permissions')}</summary><div class="setup-profile-body"><div><h3 data-i18n-preserve>${esc(c.name)}</h3><p data-i18n-preserve>${esc(c.description)}</p><p>${txt('公开资料来自配置，仅供查看。','The configured public profile is read-only.')}</p></div>${workspaceKind()==='organization'?routeButton('成员与权限','members','','user'):''}</div></details>`+
  `<div class="setup-footer">${routeButton(txt('了解开通流程','About blog setup'),'guide','quiet','help')}${setupHint()}</div>`;
}
function showSetupApplication(){
  const f=setupData.forms[setupView.formOwner];
  modal(txt('申请开通博客','Request blog setup'),`<p>${txt('所属工作区','Workspace')}：<strong data-i18n-preserve>${esc(workspaceLabel())}</strong></p>${setupField('setup-name','博客名称','Blog name',f.name,false,80)}${notice(txt('运维分配一个平台子域名，英文 /en/、中文 /zh/；根路径默认英文，不申请自定义域名。','Operations assigns one platform subdomain with /en/ and /zh/. The root opens English; custom-domain requests are not included.'))}${setupField('setup-note','给运维的备注（选填）','Note for operations (optional)',f.note,true)}<p id="setup-error" class="form-error" role="alert"></p>${setupHint()}`,btn('取消','close-modal')+flowButton('提交申请','Submit request','setup-submit','','primary'));
}
function showSetupSupplement(){setupView.formOwner=state.workspace;const r=setupData.requests[state.workspace];modal(txt('补充开通资料','Provide setup information'),notice(esc(r.infoReason))+setupField('setup-response','补充说明','Response',r.supplement,true)+'<p id="setup-error" class="form-error" role="alert"></p>',btn('取消','close-modal')+flowButton('提交补充','Send information','setup-send-supplement','','primary'));}
function showSetupInfoRequest(){modal(txt('请求补充资料','Request information'),setupField('setup-info-reason','需要补充什么？','What information is needed?','',true,600)+'<p id="setup-error" class="form-error" role="alert"></p>',btn('取消','close-modal')+flowButton('发送请求','Send request','setup-send-info','','primary'));}
function showSetupRootConfirmation(r,root){modal(txt('更新博客根地址？','Change the blog root?'),notice(txt('两种语言和根入口都需要重新核验，文章及申请不会删除。','Both languages and the root must be reverified. Articles and this request are retained.'))+`<p data-i18n-preserve>${esc(r.rootUrl)} → ${esc(root)}</p><p id="setup-error" class="form-error" role="alert"></p>`,btn('取消','close-modal')+flowButton('更新并重新核验','Change and recheck','setup-confirm-root','','primary'));}
function setupOperatorPage(){
  const r=setupView.owner?currentSetupRequest():null;
  const head=titleBlock('',txt('博客开通 · 运维演示','Blog setup · operations demo'),txt('此视角仅模拟运维处理，不赋予真实运维权限。','This view simulates operations and grants no real permissions.'),flowButton('返回我的站点','Back to my sites','setup-user','','quiet'));
  if(!r){const rows=Object.values(setupData.requests).filter(Boolean);return head+`<section class="panel setup-queue">${rows.length?rows.map(r=>`<div class="setup-queue-row"><div><strong data-i18n-preserve>${esc(r.name)}</strong><p data-i18n-preserve>${esc(workspaceLabel(r.owner))} · ${esc(r.id)}</p></div>${setupStatus(r)}${flowButton('处理申请','Open request','setup-detail',r.owner,'soft')}</div>`).join(''):emptyState(txt('暂无开通申请','No setup requests'),txt('在站点与工作区提交申请后，会出现在这里。','Requests submitted in Sites & workspace appear here.'),flowButton('返回站点','Back to sites','setup-user','','primary'))}</section>`;}
  const lang=setupView.language,s=r.sites[lang],locked=!r.assignee||r.status==='info';
  const checks={ownership:['站点归属','Ownership'],https:['HTTPS','HTTPS'],routing:['语言路径与资源','Language paths & assets'],connection:['Ghost 连接','Ghost connection'],storage:['存储配置','Storage configuration']};
  return head+flowButton('返回申请列表','Back to requests','setup-queue','','quiet')+
  `<section class="panel setup-operator"><div class="section-heading"><div><h2 data-i18n-preserve>${esc(r.name)}</h2><p data-i18n-preserve>${esc(workspaceLabel(r.owner))} · ${esc(r.id)}</p></div>${setupStatus(r)}</div>${r.note?`<p data-i18n-preserve>${esc(r.note)}</p>`:''}<div class="setup-actions">${!r.assignee?flowButton('领取申请','Claim request','setup-claim','','primary'):badge(txt('运维团队处理中','Assigned to operations'),'purple')}${r.status!=='complete'?flowButton('请求补充资料','Request information','setup-ask-info','','quiet'):''}</div>${r.status==='info'?notice(esc(r.infoReason)):''}${r.supplement?notice(esc(r.supplement)):''}<div class="setup-root-form">${setupField('setup-root','博客根地址','Blog root URL',setupData.operatorRoots[r.owner]??(r.rootUrl||setupModel.demoRootUrl(r.owner)))}<button class="btn" data-flow="setup-register-root" ${locked?'disabled':''}>${txt('登记地址','Register root')}</button></div><p class="setup-caption">${txt('示例：https://richard.chronoai.example/；登记一次，自动生成 /en/ 和 /zh/。','Example: https://richard.chronoai.example/. Register once to derive /en/ and /zh/.')}</p><div class="setup-root-check"><div><strong>${txt('根路径 → /en/','Root → /en/')}</strong><p>${txt('英文就绪后单独核验，默认语言固定为英文。','Verify separately after English is ready. The default remains English.')}</p></div>${badge(r.rootCheck.status==='passed'?txt('已通过','Passed'):txt('待核验','Pending'),r.rootCheck.status==='passed'?'green':'neutral')}<button class="btn" data-flow="setup-verify" data-flow-id="root" ${locked||r.sites.en.status!=='ready'||r.rootCheck.status==='passed'?'disabled':''}>${txt('核验根入口','Verify root')}</button></div><div class="tabs setup-tabs">${['en','zh'].map(l=>`<button class="tab ${lang===l?'active':''}" data-flow="setup-language" data-flow-id="${l}">${l==='en'?'English':'简体中文'}</button>`).join('')}</div><p class="setup-address" data-i18n-preserve>${esc(s.url||'—')}</p><div class="setup-checks">${Object.entries(checks).map(([key,words])=>{const check=s.checks.find(c=>c.key===key);return `<div><span>${txt(...words)}</span>${badge(check?(check.ok?txt('通过','Passed'):txt('失败','Failed')):s.status==='ready'?txt('已有配置','Existing configuration'):txt('待核验','Pending'),check?check.ok?'green':'red':'neutral')}</div>`;}).join('')}</div><div class="setup-actions"><button class="btn primary" data-flow="setup-verify" data-flow-id="language" ${locked||!s.url||s.status==='ready'?'disabled':''}>${txt('模拟核验通过','Simulate successful check')}</button><button class="btn quiet" data-flow="setup-verify-fail" ${locked||!s.url||s.status==='ready'?'disabled':''}>${txt('模拟 HTTPS 失败','Simulate HTTPS failure')}</button></div>${setupHint()}</section>${setupActivity(r)}`;
}
pageRenderers.settings=setupSettingsPage;
const setupOriginalEditor=pageRenderers.editor;
pageRenderers.editor=()=>{
  const missing=!isSiteReady(state.workspace,state.lang),r=setupData.requests[state.workspace];
  return (missing?`<div class="setup-editor-notice"><div><strong>${state.lang==='en'?'English':'简体中文'} · ${txt('站点尚未开通','Site not configured')}</strong><p>${txt('可以继续保存草稿和提交审核，发布前需要开通当前语言站点。','You can save drafts and submit for review. This language site must be ready before publishing.')}</p></div>${flowButton(r?'查看开通进度':'去开通站点',r?'View setup progress':'Set up site','setup-from-editor','','soft')}</div>`:'')+setupOriginalEditor();
};
const setupOriginalPublish=pageRenderers.publish;
pageRenderers.publish=()=>setupOriginalPublish()+(!isSiteReady(state.workspace,state.lang)?flowButton('查看站点开通','View site setup','setup-from-editor','','soft'):'');
const setupOriginalDemo=actions.demo;
actions.demo=()=>{
  setupOriginalDemo();
  document.querySelector('.modal-body')?.insertAdjacentHTML('beforeend',`<div class="setup-demo-section"><h3>${txt('站点开通演示','Site setup demo')}</h3><p>${txt('仅改变当前原型工作区的示例，不修改真实服务。','Changes affect this prototype workspace only, never real services.')}</p><div class="setup-actions">${flowButton('未申请场景','Not requested scenario','setup-demo-new')}${flowButton('进入运维演示','Open operations demo','setup-ops','','soft')}</div></div>`);
  applyInterfaceLocale();
};
function setupGuideSection(){return `<section class="panel setup-guide"><h2>${txt('先开通博客，再发布原文','Set up your blog before publishing')}</h2><ol><li>${txt('进入「站点与工作区」，由个人 Owner 或组织 Admin 提交博客名称。','In Sites & workspace, the personal owner or organization Admin submits the blog name.')}</li><li>${txt('运维准备同一域名下的 /en/ 和 /zh/ 两套 Ghost；根路径默认跳英文。','Operations prepares two Ghost instances at /en/ and /zh/ under one domain; the root opens English.')}</li><li>${txt('申请、补充资料和开通进度都在同一站点页查看。Member 和 Publisher 无需重复申请。','Requests, additional information and progress stay on the same sites page. Members and Publishers do not submit duplicate requests.')}</li><li>${txt('站点就绪后回到原文章，继续原有发布确认流程。开通不会自动发文。','Return to the existing article and publication confirmation when ready. Setup never publishes content automatically.')}</li></ol>${flowButton('查看当前工作区站点','View workspace sites','setup-open','','soft')}</section>`;}
